CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS organizations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),email text NOT NULL UNIQUE,name text NOT NULL,password_hash text,active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS memberships(organization_id uuid NOT NULL REFERENCES organizations(id),user_id uuid NOT NULL REFERENCES users(id),role text NOT NULL CHECK(role IN ('ADMIN','AGENT','ASSISTANT')),PRIMARY KEY(organization_id,user_id));
CREATE TABLE IF NOT EXISTS sessions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations(id),user_id uuid NOT NULL REFERENCES users(id),token_hash text NOT NULL UNIQUE,expires_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS sessions_expiry ON sessions(expires_at);
CREATE TABLE IF NOT EXISTS rate_limits(key text PRIMARY KEY,hits integer NOT NULL,expires_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS password_reset_tokens(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id),token_hash text NOT NULL UNIQUE,expires_at timestamptz NOT NULL,used_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS settings(organization_id uuid PRIMARY KEY REFERENCES organizations(id),data jsonb NOT NULL DEFAULT '{}',updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS terms_versions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations(id),version text NOT NULL,body text NOT NULL,approved boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(organization_id,version));
CREATE TABLE IF NOT EXISTS properties(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations(id),agent_id uuid NOT NULL REFERENCES users(id),code text NOT NULL,title text NOT NULL,description text NOT NULL DEFAULT '',type text NOT NULL CHECK(type IN ('CASA','APARTAMENTO','VILLA','SOLAR','TERRENO','LOCAL','FINCA','PENTHOUSE')),operation text NOT NULL DEFAULT 'VENTA' CHECK(operation IN ('VENTA','ALQUILER')),status text NOT NULL DEFAULT 'BORRADOR' CHECK(status IN ('BORRADOR','PUBLICADA','RESERVADA','VENDIDA','RETIRADA')),price_minor bigint CHECK(price_minor>=0 AND price_minor<=9007199254740991),currency text NOT NULL DEFAULT 'DOP' CHECK(currency IN ('DOP','USD')),province text NOT NULL DEFAULT '',municipality text NOT NULL DEFAULT '',sector text NOT NULL DEFAULT '',address_private text NOT NULL DEFAULT '',bedrooms integer CHECK(bedrooms>=0),bathrooms numeric CHECK(bathrooms>=0),parking integer CHECK(parking>=0),built_area numeric CHECK(built_area>=0),land_area numeric CHECK(land_area>=0),amenities jsonb NOT NULL DEFAULT '[]',owner_name text NOT NULL DEFAULT '',internal_notes text NOT NULL DEFAULT '',metadata jsonb NOT NULL DEFAULT '{}',deleted_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(organization_id,code));
CREATE INDEX IF NOT EXISTS property_search ON properties(organization_id,status,type,currency,price_minor);
CREATE INDEX IF NOT EXISTS property_zone ON properties(organization_id,municipality,sector);
CREATE TABLE IF NOT EXISTS property_media(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations(id),property_id uuid NOT NULL REFERENCES properties(id),url text NOT NULL,alt text NOT NULL DEFAULT '',width integer,height integer,position integer NOT NULL DEFAULT 0,metadata jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS media_property ON property_media(property_id,position);
CREATE TABLE IF NOT EXISTS property_documents(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations(id),property_id uuid NOT NULL REFERENCES properties(id),storage_key text NOT NULL,name text NOT NULL,mime text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS property_status_history(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations(id),property_id uuid NOT NULL REFERENCES properties(id),actor_id uuid REFERENCES users(id),from_status text,to_status text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS prospects(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations(id),agent_id uuid NOT NULL REFERENCES users(id),name text NOT NULL,email text,phone text,channel text NOT NULL DEFAULT 'MANUAL',consent boolean NOT NULL DEFAULT false,status text NOT NULL DEFAULT 'NUEVO' CHECK(status IN ('NUEVO','CALIFICADO','OFERTA_PREPARADA','OFERTA_ENVIADA','INTERESADO','VISITA_AGENDADA','NEGOCIACIÓN','GANADO','PERDIDO')),notes text NOT NULL DEFAULT '',archived_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS prospects_status ON prospects(organization_id,agent_id,status);
CREATE INDEX IF NOT EXISTS prospects_email ON prospects(organization_id,lower(email));
CREATE INDEX IF NOT EXISTS prospects_name ON prospects(organization_id,lower(name));
CREATE TABLE IF NOT EXISTS prospect_preferences(prospect_id uuid PRIMARY KEY REFERENCES prospects(id),organization_id uuid NOT NULL REFERENCES organizations(id),data jsonb NOT NULL DEFAULT '{}',updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS prospect_notes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations(id),prospect_id uuid NOT NULL REFERENCES prospects(id),actor_id uuid REFERENCES users(id),text text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS offers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations(id),agent_id uuid NOT NULL REFERENCES users(id),prospect_id uuid NOT NULL REFERENCES prospects(id),slug text NOT NULL UNIQUE,title text NOT NULL,greeting text NOT NULL DEFAULT '',introduction text NOT NULL DEFAULT '',status text NOT NULL DEFAULT 'BORRADOR' CHECK(status IN ('BORRADOR','PUBLICADA','PAUSADA','EXPIRADA','ARCHIVADA')),theme text NOT NULL DEFAULT 'MINIMALISTA' CHECK(theme IN ('MINIMALISTA','EDITORIAL','CALIDO')),expires_at timestamptz NOT NULL DEFAULT now()+interval '30 days',version integer NOT NULL DEFAULT 0,visit_policy jsonb NOT NULL DEFAULT '{}',metadata jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS offer_org_status ON offers(organization_id,agent_id,status);
CREATE INDEX IF NOT EXISTS offers_prospect ON offers(prospect_id);
CREATE TABLE IF NOT EXISTS offer_properties(offer_id uuid NOT NULL REFERENCES offers(id),property_id uuid NOT NULL REFERENCES properties(id),organization_id uuid NOT NULL REFERENCES organizations(id),position integer NOT NULL DEFAULT 0,reason text NOT NULL DEFAULT '',PRIMARY KEY(offer_id,property_id));
CREATE TABLE IF NOT EXISTS offer_versions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations(id),offer_id uuid NOT NULL REFERENCES offers(id),version integer NOT NULL,snapshot jsonb NOT NULL,actor_id uuid REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(offer_id,version));
CREATE TABLE IF NOT EXISTS access_invites(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations(id),offer_id uuid NOT NULL REFERENCES offers(id),token_hash text NOT NULL UNIQUE,expires_at timestamptz NOT NULL,revoked_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS portal_sessions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations(id),offer_id uuid NOT NULL REFERENCES offers(id),invite_id uuid NOT NULL REFERENCES access_invites(id),token_hash text NOT NULL UNIQUE,expires_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS favorites(organization_id uuid NOT NULL REFERENCES organizations(id),offer_id uuid NOT NULL REFERENCES offers(id),property_id uuid NOT NULL REFERENCES properties(id),created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(offer_id,property_id));
CREATE TABLE IF NOT EXISTS interactions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations(id),offer_id uuid NOT NULL REFERENCES offers(id),prospect_id uuid NOT NULL REFERENCES prospects(id),property_id uuid REFERENCES properties(id),kind text NOT NULL,message text NOT NULL DEFAULT '',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS availability_slots(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations(id),agent_id uuid NOT NULL REFERENCES users(id),start_at timestamptz NOT NULL,end_at timestamptz NOT NULL CHECK(end_at>start_at),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(agent_id,start_at));
CREATE INDEX IF NOT EXISTS slots_dates ON availability_slots(organization_id,start_at);
CREATE TABLE IF NOT EXISTS visits(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations(id),agent_id uuid NOT NULL REFERENCES users(id),prospect_id uuid NOT NULL REFERENCES prospects(id),offer_id uuid NOT NULL REFERENCES offers(id),property_id uuid NOT NULL REFERENCES properties(id),slot_id uuid NOT NULL REFERENCES availability_slots(id),status text NOT NULL DEFAULT 'PENDIENTE_PAGO' CHECK(status IN ('SOLICITADA','PENDIENTE_PAGO','CONFIRMADA','ASISTIÓ','NO_ASISTIÓ','CANCELADA','REPROGRAMADA','COMPLETADA')),deposit_minor bigint NOT NULL CHECK(deposit_minor>=0),currency text NOT NULL CHECK(currency IN ('DOP','USD')),mode text NOT NULL CHECK(mode IN ('sandbox','live')),terms_version text NOT NULL,property_snapshot jsonb NOT NULL,hold_expires_at timestamptz,check_in_at timestamptz,cancelled_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS visits_active_slot ON visits(slot_id) WHERE status IN ('SOLICITADA','PENDIENTE_PAGO','CONFIRMADA','ASISTIÓ','COMPLETADA');
CREATE INDEX IF NOT EXISTS visits_org ON visits(organization_id,agent_id,status);
CREATE TABLE IF NOT EXISTS terms_acceptances(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations(id),visit_id uuid NOT NULL UNIQUE REFERENCES visits(id),prospect_id uuid NOT NULL REFERENCES prospects(id),version text NOT NULL,body text NOT NULL,accepted_at timestamptz NOT NULL DEFAULT now(),source text NOT NULL);
CREATE TABLE IF NOT EXISTS visit_history(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations(id),visit_id uuid NOT NULL REFERENCES visits(id),actor_id uuid REFERENCES users(id),action text NOT NULL,details jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS payments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations(id),visit_id uuid NOT NULL UNIQUE REFERENCES visits(id),amount_minor bigint NOT NULL CHECK(amount_minor>=0),refunded_minor bigint NOT NULL DEFAULT 0 CHECK(refunded_minor>=0 AND refunded_minor<=amount_minor),currency text NOT NULL CHECK(currency IN ('DOP','USD')),status text NOT NULL DEFAULT 'PENDIENTE' CHECK(status IN ('PENDIENTE','PAGADO','FALLIDO','EXPIRADO','EN_REVISIÓN','REEMBOLSO_PENDIENTE','REEMBOLSADO','REEMBOLSO_FALLIDO','DISPUTADO')),mode text NOT NULL DEFAULT 'sandbox' CHECK(mode IN ('sandbox','live')),reference text NOT NULL UNIQUE,provider_reference text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS payment_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations(id),payment_id uuid NOT NULL REFERENCES payments(id),provider text NOT NULL,event_id text NOT NULL UNIQUE,event_type text NOT NULL,payload_hash text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS refunds(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations(id),payment_id uuid NOT NULL REFERENCES payments(id),idempotency_key text NOT NULL,amount_minor bigint NOT NULL CHECK(amount_minor>0),status text NOT NULL,reference text,evidence text,actor_id uuid REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),confirmed_at timestamptz,UNIQUE(payment_id,idempotency_key));
CREATE TABLE IF NOT EXISTS ledger_entries(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations(id),payment_id uuid NOT NULL REFERENCES payments(id),refund_id uuid REFERENCES refunds(id),kind text NOT NULL CHECK(kind IN ('DEPOSIT','REFUND')),amount_minor bigint NOT NULL CHECK(amount_minor>0),currency text NOT NULL,reference text NOT NULL UNIQUE,created_at timestamptz NOT NULL DEFAULT now());
CREATE OR REPLACE FUNCTION forbid_ledger_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Ledger entries are immutable'; END $$;
DROP TRIGGER IF EXISTS ledger_immutable ON ledger_entries;
CREATE TRIGGER ledger_immutable BEFORE UPDATE OR DELETE ON ledger_entries FOR EACH ROW EXECUTE FUNCTION forbid_ledger_mutation();
CREATE TABLE IF NOT EXISTS ai_conversations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations(id),user_id uuid NOT NULL REFERENCES users(id),prospect_id uuid REFERENCES prospects(id),title text NOT NULL DEFAULT '',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS ai_messages(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations(id),conversation_id uuid NOT NULL REFERENCES ai_conversations(id),role text NOT NULL,content jsonb NOT NULL,metadata jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS ai_runs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations(id),user_id uuid NOT NULL REFERENCES users(id),conversation_id uuid REFERENCES ai_conversations(id),idempotency_key text NOT NULL,request_hash text NOT NULL,status text NOT NULL,result jsonb,error text,usage jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(organization_id,user_id,idempotency_key));
CREATE TABLE IF NOT EXISTS tasks(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations(id),agent_id uuid REFERENCES users(id),prospect_id uuid REFERENCES prospects(id),title text NOT NULL,due_at timestamptz,status text NOT NULL DEFAULT 'PENDIENTE',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS notification_jobs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations(id),kind text NOT NULL,payload jsonb NOT NULL,status text NOT NULL DEFAULT 'BLOCKED_NO_PROVIDER',attempts integer NOT NULL DEFAULT 0,run_at timestamptz NOT NULL DEFAULT now(),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS audit_logs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations(id),actor_id uuid REFERENCES users(id),action text NOT NULL,entity_type text NOT NULL,entity_id uuid,details jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS audit_org_date ON audit_logs(organization_id,created_at DESC);
CREATE TABLE IF NOT EXISTS request_keys(organization_id uuid NOT NULL REFERENCES organizations(id),user_id uuid NOT NULL REFERENCES users(id),scope text NOT NULL,key text NOT NULL,entity_id uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(organization_id,user_id,scope,key));
CREATE INDEX IF NOT EXISTS ai_runs_dedup ON ai_runs(organization_id,user_id,request_hash,status,created_at DESC);
CREATE INDEX IF NOT EXISTS ai_conversation_history ON ai_conversations(organization_id,user_id,updated_at DESC);
CREATE INDEX IF NOT EXISTS ai_message_history ON ai_messages(organization_id,conversation_id,created_at);
